WITH cleaned AS (SELECT *, TRIM(status) AS clean_status, DATEDIFF(CURRENT_DATE(), start_date) / 7 AS weeks_since_start_date FROM subscriptions WHERE customer_id IS NOT NULL AND status = 'ACTIVE') SELECT CASE WHEN monthly_fee >= 196 THEN 'PREMIUM' ELSE 'STANDARD' END AS monthly_fee_tier, AVG(monthly_fee) FILTER (WHERE plan = 'standard') AS standard_avg_monthly_fee, COUNT(*) AS event_count, COUNT_IF(status = 'EXPIRED') AS expired_events FROM cleaned GROUP BY monthly_fee_tier ORDER BY expired_events DESC;
